#!/usr/bin/env node
/**
 * Generate search-modal tool data from the single source of truth.
 *
 * Source: packages/config/all-tools.js (the same catalogue the tools pages,
 * search page and header shortcut use).
 * Output: apps/main/dist/js/versal-tools-data.js
 *
 * The generated file assigns window.__VERSAL_TOOLS__ so the classic (non-module)
 * search-modal script can read it synchronously — no runtime fetch, no FOUC.
 * Run as part of `apps/main` build, AFTER astro build creates dist/.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import allTools from '@versal/config/all-tools.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.resolve(__dirname, '../dist/js/versal-tools-data.js');

if (!Array.isArray(allTools) || allTools.length === 0) {
  console.error('[generate-search-data] all-tools.js is empty or not an array');
  process.exit(1);
}

// Keep only the fields the modal needs; this also strips the search-only _score field.
const data = allTools.map(({ title, description, href, section, keywords }) => ({
  title,
  description,
  href,
  section,
  keywords,
}));

const json = JSON.stringify(data);
const banner = [
  '/* AUTO-GENERATED by scripts/generate-search-data.mjs — do not edit. */',
  '/* Single source: packages/config/all-tools.js */',
  `window.__VERSAL_TOOLS__ = ${json};`,
  '',
].join('\n');

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, banner, 'utf8');
console.log(`[generate-search-data] wrote ${data.length} tools -> ${path.relative(process.cwd(), OUT)} (${Buffer.byteLength(banner)} bytes)`);
